document.querySelectorAll('[data-lab="G06-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const q=s=>root.querySelector(s),pairs=q('[data-field="pairs"]'),volume=q('[data-field="volume"]'),charge=q('[data-field="charge"]'),zh=root.dataset.language==='zh';function update(){const n=Number(pairs.value),v=Number(volume.value),p=Number(charge.value),na=n+Math.max(-p,0),cl=n+Math.max(p,0),inc=1000/(6.02214076e23*v*1e-24);q('[data-read="pairs"]').textContent=n;q('[data-read="volume"]').textContent=v.toFixed(3);for(const[k,count]of[['na',na],['cl',cl]]){const h=count*4;q('[data-bar="'+k+'"]').setAttribute('y',260-h);q('[data-bar="'+k+'"]').setAttribute('height',h);q('[data-count="'+k+'"]').setAttribute('y',248-h);q('[data-count="'+k+'"]').textContent=count;}q('[data-feedback]').textContent=zh?'盐对浓度 '+(n*inc).toFixed(2)+' mM；Na⁺ '+na+'个（'+(na*inc).toFixed(2)+' mM），Cl⁻ '+cl+'个（'+(cl*inc).toFixed(2)+' mM）。加上蛋白质后总净电荷为 '+(na-cl+p)+'e。':'Salt-pair concentration '+(n*inc).toFixed(2)+' mM; Na⁺ '+na+' ('+(na*inc).toFixed(2)+' mM), Cl⁻ '+cl+' ('+(cl*inc).toFixed(2)+' mM). Including the protein, net charge is '+(na-cl+p)+'e.';}[pairs,volume].forEach(x=>x.addEventListener('input',update));charge.addEventListener('change',update);q('[data-action="reset"]').addEventListener('click',()=>{pairs.value=17;volume.value=193.424;charge.value=0;update()});update();});